import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';

/**
 * Generate a list of overdue invoices.
 * @param {Array<{ number: string, customerId: string, dueDate?: string, status: string, payments?: Array, lines: Array, voucher?: object }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format (report as of this date)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Generate a VAT summary grouped by rate.
 * @param {Array<{ status: string, lines: Array }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const included = invoices.filter(
    (inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid'
  );

  const vatGroups = {};

  for (const invoice of included) {
    for (const line of invoice.lines) {
      const rate = line.vatRate;
      if (!vatGroups[rate]) {
        vatGroups[rate] = { base: 0, vat: 0 };
      }
      const total = lineTotal(line);
      const discount = lineDiscount(line);
      const vat = lineVat(line);
      vatGroups[rate].base += total - discount;
      vatGroups[rate].vat += vat;
    }
  }

  const result = Object.entries(vatGroups)
    .map(([rate, { base, vat }]) => ({
      rate: parseInt(rate, 10),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);

  return result;
}

