    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const due = balanceDue(issued);
  const paid = recordPayment(issued, { amount: due, date: '2026-10-10' }).value;
  const fee = lateFee(paid, '2026-10-25');
  assert.equal(fee, 0);
});

test('lateFee calculates for one day overdue', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const due = balanceDue(issued);
  const fee = lateFee(issued, '2026-10-22');
  const expected = Math.round((due * 1 * 0.04) / 100);
  assert.equal(fee, expected);
});

test('lateFee calculates for multiple days overdue', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const due = balanceDue(issued);
  const fee = lateFee(issued, '2026-10-31');
  const daysOverdue = 10;
  const expected = Math.round((due * daysOverdue * 0.04) / 100);
  assert.equal(fee, expected);
});

test('lateFee uses amount still due for partial payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const partial = recordPayment(issued, { amount: 2000, date: '2026-10-10' }).value;
  const stillDue = balanceDue(partial);
  const fee = lateFee(partial, '2026-10-22');
  const expected = Math.round((stillDue * 1 * 0.04) / 100);
  assert.equal(fee, expected);
});

test('lateFee is integer cents', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const fee = lateFee(issued, '2026-10-25');
  assert.equal(Number.isInteger(fee), true);
});

test('lateFee returns non-negative', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const fee = lateFee(issued, '2026-10-25');
  assert.ok(fee >= 0);
});

